package io.github.samlinb.openbone.core;

import java.util.*;
import org.junit.jupiter.api.*;
import io.github.samlinb.openbone.core.math.*;
import io.github.samlinb.openbone.core.model.*;
import static io.github.samlinb.openbone.TestData.id;
import static org.junit.jupiter.api.Assertions.*;

class PhysicsSolverTest {
 static PhysicsConstraint fixture(List<Double> influences){return new PhysicsConstraint(id(5),"spring",0,true,id(2),influences,5000,List.of(1.,0.,1.,1.,1.,1.,1.));}
 static PhysicsSolver.Result start(PhysicsConstraint c){return PhysicsSolver.apply(c,Affine2.IDENTITY,100,PhysicsSolver.State.ZERO,PhysicsSolver.Mode.RESET);}
 static void near(double a,double b){IkConstraintTest.near(a,b);}
 @Test void windGravityMassAndDampingHaveIndependentStepEquations(){var p=fixture(List.of(1.,1.,0.,0.,0.)).withParameter(2,.5).withParameter(3,2);var initial=start(p);assertEquals(0,initial.state().steps());double dt=PhysicsConstraint.STEP,force=100/2.;var first=PhysicsSolver.apply(p,Affine2.IDENTITY,100,initial.state(),PhysicsSolver.Mode.UPDATE);near(force*dt*dt,first.matrix().tx());near(-force*dt*dt,first.matrix().ty());near(force*dt*.5,first.state().xVelocity());var next=PhysicsSolver.apply(p,Affine2.IDENTITY,100,first.state(),PhysicsSolver.Mode.UPDATE);near(force*dt*dt*2.5,next.matrix().tx());near(-force*dt*dt*2.5,next.matrix().ty());assertEquals(2,next.state().steps());}
 @Test void inertiaLimitAndMixAreAppliedAfterInputMotion(){var p=fixture(List.of(1.,0.,0.,0.,0.)).withParameter(4,0).withParameter(6,.5).withLimit(60);var initial=start(p);var moved=new Transform(100,0,0,1,1).matrix();var result=PhysicsSolver.apply(p,moved,100,initial.state(),PhysicsSolver.Mode.UPDATE);near(99.5,result.matrix().tx());near(-1,result.state().xOffset());assertEquals(moved,PhysicsSolver.apply(p.withEnabled(false),moved,100,initial.state(),PhysicsSolver.Mode.UPDATE).matrix());}
 @Test void strengthRestoresOffsetBeforeDamping(){var p=fixture(List.of(1.,0.,0.,0.,0.)).withParameter(1,100).withParameter(4,0).withLimit(60);var moved=new Transform(100,0,0,1,1).matrix();var next=PhysicsSolver.apply(p,moved,100,start(p).state(),PhysicsSolver.Mode.UPDATE);double dt=PhysicsConstraint.STEP;near(-1+100*dt*dt,next.state().xOffset());near(100*dt,next.state().xVelocity());}
 @Test void rotateShearAndScaleAffectDistinctMatrixColumns(){double angle=-PhysicsConstraint.STEP*PhysicsConstraint.STEP;for(boolean shear:new boolean[]{false,true}){var p=fixture(shear?List.of(0.,0.,0.,0.,1.):List.of(0.,0.,1.,0.,0.)).withParameter(4,0);var next=PhysicsSolver.apply(p,Affine2.IDENTITY,100,start(p).state(),PhysicsSolver.Mode.UPDATE);near(Math.cos(angle),next.matrix().a());near(Math.sin(angle),next.matrix().c());near(shear?0:-Math.sin(angle),next.matrix().b());near(shear?1:Math.cos(angle),next.matrix().d());}var p=fixture(List.of(0.,0.,0.,1.,0.)).withParameter(5,0);var next=PhysicsSolver.apply(p,Affine2.IDENTITY,100,start(p).state(),PhysicsSolver.Mode.UPDATE);near(1+PhysicsConstraint.STEP*PhysicsConstraint.STEP,next.matrix().a());near(1,next.matrix().d());}
 @Test void nonePoseResetAndZeroLengthDoNotIntegrateTwice(){var p=fixture(List.of(1.,0.,0.,1.,0.));var state=start(p).state();var step=PhysicsSolver.apply(p,Affine2.IDENTITY,0,state,PhysicsSolver.Mode.UPDATE);assertEquals(state,PhysicsSolver.apply(p,Affine2.IDENTITY,100,state,PhysicsSolver.Mode.NONE).state());var posed=PhysicsSolver.apply(p,Affine2.IDENTITY,0,step.state(),PhysicsSolver.Mode.POSE);assertEquals(step.state(),posed.state());assertEquals(step.matrix(),posed.matrix());assertEquals(start(p).state(),PhysicsSolver.apply(p,Affine2.IDENTITY,100,step.state(),PhysicsSolver.Mode.RESET).state());}
 @Test void tenReplaysAreStepwiseBitIdentical(){var p=fixture(List.of(1.,1.,1.,.5,.25)).withParameter(1,100).withParameter(2,.95);List<PhysicsSolver.Result> baseline=new ArrayList<>();for(int run=0;run<10;run++){var state=start(p).state();for(int step=1;step<=600;step++){var input=new Transform(Math.sin(step*.03)*20,Math.cos(step*.02)*10,step*.1,1,.8).matrix();var result=PhysicsSolver.apply(p,input,100,state,PhysicsSolver.Mode.UPDATE);state=result.state();if(run==0)baseline.add(result);else assertEquals(baseline.get(step-1),result);}}}
 @Test void invalidOrUnstableParametersAreRejectedBeforeState(){var p=fixture(List.of(1.,1.,0.,0.,0.));assertThrows(IllegalArgumentException.class,()->p.withParameter(3,0));assertThrows(IllegalArgumentException.class,()->p.withParameter(1,4000));assertThrows(IllegalArgumentException.class,()->p.withParameter(2,1.1));assertThrows(IllegalArgumentException.class,()->p.withInfluence(0,-1));}
 @Test void overflowingInputDifferenceIsNotHiddenByTheLimitClamp(){var p=fixture(List.of(1.,0.,0.,0.,0.));var previous=PhysicsSolver.apply(p,new Transform(1e308,0,0,1,1).matrix(),0,PhysicsSolver.State.ZERO,PhysicsSolver.Mode.RESET).state();assertThrows(IllegalArgumentException.class,()->PhysicsSolver.apply(p,new Transform(-1e308,0,0,1,1).matrix(),0,previous,PhysicsSolver.Mode.UPDATE));}
 @Test void subnormalForceRemainsInsideTheWholeHorizonEnvelope(){var p=fixture(List.of(1.,0.,0.,0.,0.)).withLimit(0).withParameter(3,.001).withParameter(4,Double.MIN_VALUE).withParameter(5,0);var bound=PhysicsEnvelope.whole(p,1,0,100);var result=PhysicsSolver.apply(p,Affine2.IDENTITY,100,start(p).state(),PhysicsSolver.Mode.UPDATE);assertTrue(result.state().xOffset()>0);assertTrue(result.state().xOffset()<=bound.xyOffset());assertTrue(result.matrix().tx()<=bound.positionNorm());}
}
